cd /gin && cat > zz_probe_test.go <<'EOF'
package gin

import (
	"testing"
)

func TestZZProbeCIP(t *testing.T) {
	tree := &node{}
	for _, r := range []string{"/x/y", "/x/:id"} {
		func() {
			defer func() {
				if r := recover(); r != nil {
					t.Logf("panic adding %s: %v", r, r)
				}
			}()
			tree.addRoute(r, fakeHandler(r))
		}()
	}
	dumpNode(tree, 0, t)
	for _, p := range []string{"/X/Y", "/X/Z", "/x/y", "/x/z"} {
		func() {
			defer func() {
				if r := recover(); r != nil {
					t.Logf("findCaseInsensitivePath(%q) PANIC: %v", p, r)
				}
			}()
			out, found := tree.findCaseInsensitivePath(p, true)
			t.Logf("findCaseInsensitivePath(%q) = %q, %v", p, string(out), found)
		}()
	}
}

func dumpNode(n *node, depth int, t *testing.T) {
	t.Logf("%*spath=%q indices=%q wildChild=%v nType=%d handlers=%v", depth*2, "", n.path, n.indices, n.wildChild, n.nType, n.handlers != nil)
	for _, c := range n.children {
		dumpNode(c, depth+1, t)
	}
}
EOF
go test -run TestZZProbeCIP -v . 2>&1 | head -40
